def get_catalog_providers() -> List[Dict[str, Any]]:
    """Return all providers known to the catalog."""
    return list(KNOWN_PROVIDERS)


def find_catalog_provider(name_or_id: str) -> Optional[Dict[str, Any]]:
    """Lookup provider in catalog by id or alias (case-insensitive)."""
    q = name_or_id.strip().lower()
    for p in KNOWN_PROVIDERS:
        if p["id"].lower() == q or p.get("alias", "").lower() == q:
            return p
    for p in KNOWN_PROVIDERS:
        if q in p["name"].lower():
            return p
    return None


def is_no_auth_provider(provider_id: str) -> bool:
    """Check if provider requires zero authentication."""
    p = find_catalog_provider(provider_id)
    return bool(p and p.get("no_auth"))


def register_free_provider(provider_id: str, name: Optional[str] = None) -> Dict[str, Any]:
    """Register a free/no-auth provider directly into 9router sqlite db."""
    data_dir = get_data_dir()
    db_path = data_dir / "db" / "data.sqlite"
    if not db_path.is_file():
        raise RuntimeError(f"9router database not found at {db_path}")

    cat_p = find_catalog_provider(provider_id)
    canonical_id = cat_p["id"] if cat_p else provider_id
    display_name = name or (cat_p["name"] if cat_p else canonical_id)

    conn = sqlite3.connect(str(db_path))
    cur = conn.cursor()
    try:
        cur.execute("SELECT id, name, isActive FROM providerConnections WHERE provider = ?", (canonical_id,))
        row = cur.fetchone()
        if row:
            conn_id, c_name, is_active = row
            if not is_active:
                cur.execute("UPDATE providerConnections SET isActive = 1, updatedAt = ? WHERE id = ?", (
                    datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
                    conn_id
                ))
                conn.commit()
                return {"id": conn_id, "provider": canonical_id, "name": c_name, "action": "reactivated"}
            return {"id": conn_id, "provider": canonical_id, "name": c_name, "action": "already_active"}

        conn_id = str(uuid.uuid4())
        now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        cur.execute("""
            INSERT INTO providerConnections (id, provider, authType, name, email, priority, isActive, data, createdAt, updatedAt)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (conn_id, canonical_id, "free", display_name, None, 1, 1, "{}", now, now))
        conn.commit()
        return {"id": conn_id, "provider": canonical_id, "name": display_name, "action": "created"}
    finally:
        conn.close()
